import{_ as i,o as t,c as a,a as o}from"./app.DLPSkIGI.js";const u=JSON.parse('{"title":"Shell to Rust/Go Migration Plan","description":"","frontmatter":{},"headers":[],"relativePath":"migration/RUST_GO_MIGRATION_PLAN.md","filePath":"migration/RUST_GO_MIGRATION_PLAN.md","lastUpdated":1771753292000}'),l={name:"migration/RUST_GO_MIGRATION_PLAN.md"};function s(r,e,n,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="shell-to-rust-go-migration-plan" tabindex="-1">Shell to Rust/Go Migration Plan <a class="header-anchor" href="#shell-to-rust-go-migration-plan" aria-label="Permalink to &quot;Shell to Rust/Go Migration Plan&quot;">​</a></h1><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>Shell scripts are causing performance issues:</p><ul><li><code>which</code> command timing out (2m 43s)</li><li>Shell initialization overhead from wrapper functions</li><li>Expensive operations in hot paths (PATH resolution, process scanning)</li></ul><h2 id="root-cause-analysis" tabindex="-1">Root Cause Analysis <a class="header-anchor" href="#root-cause-analysis" aria-label="Permalink to &quot;Root Cause Analysis&quot;">​</a></h2><h3 id="why-which-times-out" tabindex="-1">Why <code>which</code> Times Out <a class="header-anchor" href="#why-which-times-out" aria-label="Permalink to &quot;Why `which` Times Out&quot;">​</a></h3><ol><li>undefined<strong>Shell Wrapper Functions</strong>: <code>common.sh</code> defines wrappers for <code>find</code>, <code>git</code>, <code>codex</code>, etc.</li><li>undefined<strong>PATH Resolution</strong>: When <code>which</code> runs, it triggers PATH scanning</li><li>undefined<strong>Cascade Effect</strong>: Each wrapper calls <code>command -v</code> which may trigger more wrappers</li><li>undefined<strong>Tool Detection</strong>: <code>common.sh</code> runs tool detection on every source, calling <code>command -v</code> multiple times</li></ol><h3 id="performance-bottlenecks" tabindex="-1">Performance Bottlenecks <a class="header-anchor" href="#performance-bottlenecks" aria-label="Permalink to &quot;Performance Bottlenecks&quot;">​</a></h3><ol><li><p>undefined<strong>hooks/lib/common.sh</strong> (1674 lines)</p><ul><li>Tool detection: <code>command -v</code> calls for jaq, jq, rg, fd, pgrep, timeout</li><li>PATH resolution: <code>resolve_real_binary()</code> function</li><li>Git wrapper: Process tree walking for agent detection</li><li>Find wrapper: File system operations</li></ul></li><li><p>undefined<strong>hooks/lib/fd-wrapper.sh</strong>undefined</p><ul><li>File discovery wrapper</li><li>Called frequently by hooks</li></ul></li><li><p>undefined<strong>hooks/lib/git-cache.sh</strong>undefined</p><ul><li>Git command caching</li><li>File I/O for cache management</li></ul></li></ol><h2 id="migration-priority" tabindex="-1">Migration Priority <a class="header-anchor" href="#migration-priority" aria-label="Permalink to &quot;Migration Priority&quot;">​</a></h2><h3 id="phase-1-critical-path-immediate" tabindex="-1">Phase 1: Critical Path (Immediate) <a class="header-anchor" href="#phase-1-critical-path-immediate" aria-label="Permalink to &quot;Phase 1: Critical Path (Immediate)&quot;">​</a></h3><ol><li><p>undefined<strong>Tool Detection</strong> → Rust binary</p><ul><li>Current: Multiple <code>command -v</code> calls in <code>common.sh</code></li><li>Target: Single Rust binary <code>thegent-tool-detect</code> that caches results</li><li>Benefit: Eliminate 60ms+ overhead per hook invocation</li></ul></li><li><p>undefined<strong>PATH Resolution</strong> → Rust function</p><ul><li>Current: <code>resolve_real_binary()</code> bash function</li><li>Target: Rust function in <code>thegent-discovery</code> crate</li><li>Benefit: 10-50x faster PATH scanning</li></ul></li><li><p>undefined<strong>Process Scanning</strong> → Already in Rust (<code>thegent-discovery</code>)</p><ul><li>Current: Python fallback using <code>ps</code> and <code>subprocess</code></li><li>Target: Use native Rust extension (needs build)</li><li>Benefit: 100x faster process tree walking</li></ul></li></ol><h3 id="phase-2-high-impact-next-sprint" tabindex="-1">Phase 2: High Impact (Next Sprint) <a class="header-anchor" href="#phase-2-high-impact-next-sprint" aria-label="Permalink to &quot;Phase 2: High Impact (Next Sprint)&quot;">​</a></h3><ol start="4"><li><p>undefined<strong>Git Operations</strong> → Rust binary (<code>thegent-git</code> crate exists)</p><ul><li>Current: Bash wrapper with mutex handling</li><li>Target: Use <code>thegent-git</code> crate for all git operations</li><li>Benefit: Better lock handling, faster operations</li></ul></li><li><p>undefined<strong>File Discovery</strong> → Rust binary (<code>fd</code> wrapper)</p><ul><li>Current: Bash wrapper calling <code>fd</code> or <code>find</code></li><li>Target: Native Rust implementation</li><li>Benefit: Eliminate subprocess overhead</li></ul></li></ol><h3 id="phase-3-optimization-future" tabindex="-1">Phase 3: Optimization (Future) <a class="header-anchor" href="#phase-3-optimization-future" aria-label="Permalink to &quot;Phase 3: Optimization (Future)&quot;">​</a></h3><ol start="6"><li>undefined<strong>Hook Dispatchers</strong> → Go binary <ul><li>Current: Bash scripts (<code>pretool-dispatcher.sh</code>, <code>posttool-dispatcher.sh</code>)</li><li>Target: Go binary for better concurrency</li><li>Benefit: Parallel hook execution, better error handling</li></ul></li></ol><h2 id="implementation-strategy" tabindex="-1">Implementation Strategy <a class="header-anchor" href="#implementation-strategy" aria-label="Permalink to &quot;Implementation Strategy&quot;">​</a></h2><h3 id="step-1-build-rust-extension-immediate" tabindex="-1">Step 1: Build Rust Extension (Immediate) <a class="header-anchor" href="#step-1-build-rust-extension-immediate" aria-label="Permalink to &quot;Step 1: Build Rust Extension (Immediate)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> thegent/crates/thegent-discovery</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">maturin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> develop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="step-2-create-fast-tool-detection-binary" tabindex="-1">Step 2: Create Fast Tool Detection Binary <a class="header-anchor" href="#step-2-create-fast-tool-detection-binary" aria-label="Permalink to &quot;Step 2: Create Fast Tool Detection Binary&quot;">​</a></h3><p>Create <code>thegent/crates/thegent-tool-detect/src/main.rs</code>:</p><ul><li>Single binary that detects all tools</li><li>Caches results in <code>/tmp/thegent-tools-{uid}.cache</code></li><li>Returns JSON with tool paths</li><li>Called once per session instead of per-hook</li></ul><h3 id="step-3-migrate-path-resolution" tabindex="-1">Step 3: Migrate PATH Resolution <a class="header-anchor" href="#step-3-migrate-path-resolution" aria-label="Permalink to &quot;Step 3: Migrate PATH Resolution&quot;">​</a></h3><p>Move <code>resolve_real_binary()</code> to Rust:</p><ul><li>Add to <code>thegent-discovery</code> crate</li><li>Expose as Python function</li><li>Update <code>common.sh</code> to call Python function (temporary)</li><li>Eventually replace <code>common.sh</code> entirely</li></ul><h3 id="step-4-replace-shell-wrappers" tabindex="-1">Step 4: Replace Shell Wrappers <a class="header-anchor" href="#step-4-replace-shell-wrappers" aria-label="Permalink to &quot;Step 4: Replace Shell Wrappers&quot;">​</a></h3><p>Gradually replace bash wrappers:</p><ol><li>Keep bash wrappers as fallback</li><li>Add Rust/Go binaries that do the same work</li><li>Update hooks to prefer binaries</li><li>Remove bash wrappers once stable</li></ol><h2 id="expected-performance-improvements" tabindex="-1">Expected Performance Improvements <a class="header-anchor" href="#expected-performance-improvements" aria-label="Permalink to &quot;Expected Performance Improvements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Current (bash)</th><th>Target (Rust/Go)</th><th>Speedup</th></tr></thead><tbody><tr><td>Tool detection</td><td>60ms</td><td>1ms</td><td>60x</td></tr><tr><td>PATH resolution</td><td>20ms</td><td>0.5ms</td><td>40x</td></tr><tr><td>Process scanning</td><td>50ms</td><td>0.5ms</td><td>100x</td></tr><tr><td>Git operations</td><td>100ms</td><td>10ms</td><td>10x</td></tr><tr><td>File discovery</td><td>30ms</td><td>2ms</td><td>15x</td></tr><tr><td>Hook dispatch</td><td>200ms</td><td>50ms</td><td>4x</td></tr></tbody></table><h2 id="migration-checklist" tabindex="-1">Migration Checklist <a class="header-anchor" href="#migration-checklist" aria-label="Permalink to &quot;Migration Checklist&quot;">​</a></h2><ul><li>[ ] Build <code>thegent_discovery</code> Rust extension</li><li>[ ] Create <code>thegent-tool-detect</code> binary</li><li>[ ] Migrate PATH resolution to Rust</li><li>[ ] Update <code>common.sh</code> to use Rust functions</li><li>[ ] Migrate git operations to <code>thegent-git</code></li><li>[ ] Create Rust file discovery binary</li><li>[ ] Migrate hook dispatchers to Go</li><li>[ ] Remove bash wrapper functions</li><li>[ ] Performance testing and validation</li></ul><h2 id="immediate-fixes" tabindex="-1">Immediate Fixes <a class="header-anchor" href="#immediate-fixes" aria-label="Permalink to &quot;Immediate Fixes&quot;">​</a></h2><h3 id="fix-which-timeout" tabindex="-1">Fix <code>which</code> Timeout <a class="header-anchor" href="#fix-which-timeout" aria-label="Permalink to &quot;Fix `which` Timeout&quot;">​</a></h3><ol><li><p>undefined<strong>Skip shell initialization for <code>which</code></strong>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In .zshrc or .bashrc</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">which</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    command</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> which</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></li><li><p>undefined<strong>Lazy load <code>common.sh</code></strong>:</p><ul><li>Only source when actually needed</li><li>Don&#39;t source during PATH resolution</li></ul></li><li><p>undefined<strong>Cache tool paths</strong>:</p><ul><li>Use existing <code>_TOOL_CACHE_FILE</code> mechanism</li><li>Pre-populate cache on shell startup (background)</li></ul></li></ol><h2 id="files-to-migrate" tabindex="-1">Files to Migrate <a class="header-anchor" href="#files-to-migrate" aria-label="Permalink to &quot;Files to Migrate&quot;">​</a></h2><h3 id="high-priority-performance-critical" tabindex="-1">High Priority (Performance Critical) <a class="header-anchor" href="#high-priority-performance-critical" aria-label="Permalink to &quot;High Priority (Performance Critical)&quot;">​</a></h3><ul><li><code>hooks/lib/common.sh</code> → Rust library + Python bindings</li><li><code>hooks/lib/fd-wrapper.sh</code> → Rust binary</li><li><code>hooks/lib/git-cache.sh</code> → Rust binary (use <code>thegent-git</code>)</li><li><code>hooks/lib/git-wrapper.sh</code> → Rust binary (use <code>thegent-git</code>)</li></ul><h3 id="medium-priority-frequently-called" tabindex="-1">Medium Priority (Frequently Called) <a class="header-anchor" href="#medium-priority-frequently-called" aria-label="Permalink to &quot;Medium Priority (Frequently Called)&quot;">​</a></h3><ul><li><code>hooks/pretool-dispatcher.sh</code> → Go binary</li><li><code>hooks/posttool-dispatcher.sh</code> → Go binary</li><li><code>hooks/lib/procs-wrapper.sh</code> → Rust binary</li></ul><h3 id="low-priority-less-critical" tabindex="-1">Low Priority (Less Critical) <a class="header-anchor" href="#low-priority-less-critical" aria-label="Permalink to &quot;Low Priority (Less Critical)&quot;">​</a></h3><ul><li>Individual hook scripts (keep as bash for flexibility)</li><li>Utility scripts (migration scripts, etc.)</li></ul><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul>',45)])])}const m=i(l,[["render",s]]);export{u as __pageData,m as default};
